// The word bank and sentence bank are generated by scripts/build-content.mjs and
// shipped as static JSON. They are fetched at boot instead of being bundled into
// the module graph, so a 3 MB bank never blocks parsing of the interface.
const BASE = 'data/';

async function defaultFetchJSON(path) {
  const response = await fetch(path, { credentials: 'same-origin' });
  if (!response.ok) throw new Error(`${path} 读取失败（${response.status}）`);
  return response.json();
}

export async function loadContent({ fetchJSON = defaultFetchJSON } = {}) {
  const [wordDoc, sentenceDoc, paperIndex] = await Promise.all([
    fetchJSON(`${BASE}words.json`),
    fetchJSON(`${BASE}sentences.json`),
    fetchJSON(`${BASE}papers/index.json`).catch(() => ({ sets: [] })),
  ]);
  const words = wordDoc.words;
  const sentences = sentenceDoc.items;
  const wordById = new Map(words.map(word => [word.id, word]));
  const sentenceById = new Map(sentences.map(sentence => [sentence.id, sentence]));
  const papers = new Map();
  return {
    words,
    sentences,
    counts: wordDoc.counts,
    sentenceCounts: sentenceDoc.counts,
    generatedAt: wordDoc.generatedAt,
    wordById: id => wordById.get(id),
    sentenceById: id => sentenceById.get(id),
    paperSets: paperIndex.sets,
    // One paper is ~25 KB; load a set only when the learner opens it.
    async paper(setId) {
      const cached = papers.get(setId);
      if (cached) return cached;
      const paper = await fetchJSON(`${BASE}papers/${setId}.json`);
      papers.set(setId, paper);
      return paper;
    },
  };
}

// Words and prompts are keyed by headword / paper question, so the display form
// is derived from the id rather than carried as a second field.
export const headword = word => word.id;
export const promptText = sentence => sentence.direction === 'zh2en' ? sentence.zh : sentence.en;
// CET-6 汉译英真题只有中文原段：阅卷由人完成，这里没有可对照的官方参考译文。
export const referenceText = sentence => sentence.direction === 'zh2en' ? (sentence.en || null) : sentence.zh;
export const hasReference = sentence => referenceText(sentence) !== null;
export const isBackTranslation = sentence => sentence.direction === 'zh2en';
export const promptIsEnglish = sentence => sentence.direction !== 'zh2en';
export const sourceLabel = sentence => sentence.source || 'Daily English 原创长句';
export const kindLabel = sentence => sentence.kind === 'paragraph' ? '段落翻译' : isBackTranslation(sentence) ? '汉译英' : '长难句';
export const answerLabel = sentence => isBackTranslation(sentence) ? '你的英文译文' : '你的译文';

// Three honest signals from the corpus, in place of invented difficulty scores.
export const examTier = (word, exam) => word.tiers?.[exam] || '';
const TIER_RANK = { '高频': 3, '中频': 2, '低频': 1 };
// The merged bank has one card per headword; show the strongest tier either exam
// assigned instead of hiding the word's relevance in the other track.
export const bestTier = word => ['cet6', 'postgrad']
  .map(exam => word.tiers?.[exam])
  .filter(Boolean)
  .sort((a, b) => (TIER_RANK[b] || 0) - (TIER_RANK[a] || 0))[0] || '';
export const paperHits = (word, exam) => word.hits?.[exam] || 0;
export const paperYears = (word, exam) => word[`${exam}Years`] || 0;
export const examLabel = exam => exam === 'cet6' ? 'CET-6 真题' : '考研真题';

// A paper is sections → groups, and a group is one exercise sheet. Flattening it
// once here gives the view and the controller the same "0-1" address for a sheet,
// so a stored score always points back at the sheet that produced it.
export const paperGroupIndex = (section, group) => `${section}-${group}`;
export const paperGroupKey = (setId, index) => `${setId}#${index}`;
export function paperGroups(paper) {
  const list = [];
  (paper?.sections || []).forEach((section, si) => (section.groups || []).forEach((group, gi) => {
    const choice = group.questions.some(q => q.options);
    // A Part B sheet ships the answer letters with no A–G sentences to choose from,
    // so it cannot be answered: it stays readable, and says so.
    const written = !choice && (group.type === 'translation_full' || group.questions.some(q => q.stem));
    list.push({
      ...group,
      index: paperGroupIndex(si, gi),
      key: paperGroupKey(paper.id, paperGroupIndex(si, gi)),
      section: section.title,
      instructions: section.instructions || '',
      sectionScore: section.score,
      answerable: choice || written,
      translation: written,
    });
  }));
  return list;
}
export const paperGroupLabel = group => group.type === 'cloze' ? '完形填空'
  : group.type === 'reading' ? (group.title || '阅读理解')
  : group.type === 'translation_full' ? '段落翻译'
  : group.type === 'translation_sentences' ? '划线句子翻译'
  : group.type === 'gap_fill' ? '新题型 Part B'
  : group.title || '真题';
// The blanks in a cloze or Part B passage are "{{7}}"; they become chips that carry
// the chosen letter, so the passage shows the sheet the way an answer sheet does.
export function paperPassage(group, { answers = {}, checked = false } = {}) {
  return (group.passage || []).map(line => escapeAndRestore(line)
    .replace(/\{\{(\d{1,2})\}\}/g, (_, number) => {
      const question = group.questions.find(q => String(q.number) === number);
      const picked = answers[number] || answers[Number(number)] || '';
      if (!question?.options) return `<span class="paper-blank is-plain">${number}</span>`;
      const right = picked === question.answer;
      return `<span class="paper-blank ${checked ? (right ? 'is-correct' : picked ? 'is-wrong' : '') : picked ? 'is-picked' : ''}">${picked || number}</span>`;
    })
    .replace(/&lt;u&gt;/g, '<em class="paper-underlined">').replace(/&lt;\/u&gt;/g, '</em>')
    .replace(/\s*\n\s*/g, ' ')).join('');
}
const escapeAndRestore = text => String(text ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
